#include <iostream>
#include <string>
using namespace std;

const int MAXM = 1005;
int data[MAXM];
int frontP = 0, rearP = 0, m;

int main() {
    int q;
    if (!(cin >> m >> q)) return 0;

    while (q--) {
        string op;
        cin >> op;
        if (op == "enqueue") {
            long long x; cin >> x;
            if ((rearP + 1) % m != frontP) {   // 不满才入队
                data[rearP] = (int)x;
                rearP = (rearP + 1) % m;
            }
        } else if (op == "dequeue") {
            if (frontP == rearP) { cout << "error\n"; continue; }
            cout << data[frontP] << "\n";
            frontP = (frontP + 1) % m;
        } else if (op == "front") {
            if (frontP == rearP) { cout << "error\n"; continue; }
            cout << data[frontP] << "\n";
        } else if (op == "size") {
            cout << (rearP - frontP + m) % m << "\n";
        }
    }
    return 0;
}
